[URL Rewrite]
request if ${url} ~= /^https?:\/\/app\.variflight\.com\/ad\//i then reject(404)
request if ${url} ~= /^https?:\/\/app\.variflight\.com\/v\d\/advert\//i then reject(404)

[Rule]
DOMAIN, adv-adlog.variflight.com,REJECT
DOMAIN, adv-ads.variflight.com,REJECT
DOMAIN, app-ad.variflight.com,REJECT

[MITM]
hostname = %APPEND% app.variflight.com
